package eu.wohlben.qits.cli.bootstrap.platform;

import java.util.Map;

/**
 * The seed stack and qits-deployments' run-args, generated. Both are ports of the heredocs in
 * {@code qits-local-up.sh}, comments and all: the comments are where the reasons live, and a
 * generated file nobody can read is a file nobody can fix.
 * <p>
 * <b>Every service below is keyed and named by its WIRE ALIAS</b> — {@code prod-qits-ci} for an
 * environment service, {@code qits-platform-idp} for a platform one, exactly what
 * {@link PlatformModel#wireAlias} derives and exactly what the deployer will give the container
 * that replaces it. A container's own name resolves on a user-defined network the way an alias
 * does, so naming the seed after the alias is what makes the addresses in this very file — and in
 * the run-args beside it — right from the first second rather than from the first cutover. It is
 * also how the deployer finds its predecessor: it searches the qualified alias AND the bare
 * application name, so a seed under either spelling is adopted rather than left running beside its
 * replacement.
 */
public final class ComposeTemplate {

    private ComposeTemplate() {
    }

    public static String compose(Map<String, String> values) {
        return Tokens.apply(COMPOSE, values);
    }

    public static String runArgs(Map<String, String> values) {
        return Tokens.apply(RUN_ARGS, values);
    }

    private static final String COMPOSE = """
            # Generated by qits-cli-bootstrap — the SEED of the local qits platform: only the services that
            # build and deploy the rest. Everything else (observability, stt, projects, workspaces, docs) is
            # deployed by qits-deployments through the main pipeline and is deliberately NOT in this file —
            # look for it in `docker ps` under qits-pd-${ENV_NAME}-qits-* container names (qits-pd-qits-* for
            # the four platform services), redeployed on every green push.
            #
            # Manage with: docker compose -p qits -f ${COMPOSE_FILE} ps|logs -f|down
            # (compose down leaves deployed containers running; remove those via the deployer's API or docker.)

            name: qits

            networks:
              qits-net:
                # The one shared network: seed services, deployed applications and ci step containers all
                # join it and resolve each other by alias. It is the deployer's
                # qits.platform.deployments.legacy-network, which every container it starts also joins while
                # the platform still holds direct cross-application URLs. External because the bootstrap (or a previous stack, or qits-ci's
                # own boot) may have created it already — compose refuses to adopt a network it did not
                # label.
                name: qits-net
                external: true

            volumes:
              # Every volume is keyed by the APPLICATION it belongs to, because the deployer's run-args
              # reference them by name and an application's run-args are looked up by that same name.
              #
              # THERE IS NO VOLUME PER DATABASE ANY MORE. Six services kept a file H2 under /data and
              # moved to the postgres below: the deployer, qits-ci (twice), qits-platform-idp,
              # qits-projects, qits-workspaces and qits-events. Where /data held the H2 and nothing else
              # — ci, the idp, events, the deployer — the volume is gone with it and the images have no
              # mount point left to give it. Where /data holds files as well, the volume stays and only
              # the datasource left it.
              #
              # THE BYTE PLANE'S THREE STORES, one volume each, and the split is why there are three.
              # Every one of them is a content-addressed blob store, and no two of them may share a
              # directory: the stores would not corrupt each other, but each one's reclaim sweep counts
              # every file it did not put there as unreferenced and deletes it.
              #
              # qits-artifacts holds the platform's OWN packages — npm, maven, OCI, the daemon binaries
              # and the docs bundles — and is the one service still on a file H2, so its /data carries the
              # database too. qits-platform-mirror holds what it cached from upstream, which is why it can
              # start cold and warm up. qits-githost holds the repositories, as packs and reftables that
              # are ordinary blobs — a git repository on this platform is not a directory anywhere.
              qits-artifacts-data:
                name: qits-artifacts-data
              qits-platform-mirror-data:
                name: qits-platform-mirror-data
              qits-githost-data:
                name: qits-githost-data
              # THE PLATFORM'S TOPOLOGY, ITS DEPLOYMENT HISTORY AND EVERY DATABASE THIS PLATFORM RUNS
              # LIVE HERE — every environment, every service, every link, every deployment row and the
              # rollback pins read off them, the credentials of every database the deployer provisions,
              # and the idp's signing key. An idp on ephemeral storage comes up healthy and mints a new
              # keypair on every recreate, invalidating every token in flight with nothing in any log to
              # say why; that is now this volume's problem to prevent rather than one of its own.
              #
              # THE MOUNT PATH IS /var/lib/postgresql AND NOT /var/lib/postgresql/data. postgres 18 puts
              # PGDATA at /var/lib/postgresql/18/docker, so a volume mounted at the old data path is
              # mounted beside the cluster rather than over it: everything works, everything is fast, and
              # every byte is written into the container's own layer and lost on the next recreate.
              qits-oci-postgresql-data:
                name: qits-oci-postgresql-data
              # Mounted by DEPLOYED containers via qits.platform.deployments.run-args, not by any service
              # below. Each one holds FILES that no database replaced: qits-projects' git mirrors and the
              # credentials beside them, qits-workspaces' per-repository trees, qits-stt's models.
              qits-projects-data:
                name: qits-projects-data
              qits-workspaces-data:
                name: qits-workspaces-data
              qits-stt-data:
                name: qits-stt-data
              # The deployer's run-args config (config/application.properties, written by the bootstrap). A
              # volume rather than env so a self-update's successor inherits it — env cannot nest these
              # values.
              qits-deployments-config:
                name: qits-deployments-config${LETSENCRYPT_VOLUME}

            # Each key below is the service's WIRE ALIAS, and so is its container_name: a container's own
            # name resolves on this network exactly as an alias does, so the seed answers to the address
            # every run-arg in the generated properties file already carries. An environment service is
            # ${ENV_NAME}-qits-<app>; a platform service is its bare repository name, which says the plane
            # itself.
            services:
              # The issuer. No published host port and no gateway route: in phase 1 nothing outside qits-net
              # talks to it, and /idp/token reachable from the host through an unauthenticated gateway would be
              # a token vending machine. Phase 3's user flows are what put it on the route table.
              #
              # First in this file because it is first in the order that matters: every service below mints or
              # validates against it, and the git host's very first post-receive needs a token.
              qits-platform-idp:
                image: qits/platform-idp:latest
                container_name: qits-platform-idp
                environment:
                  # THE STORE, and the signing key is in it: an idp that comes up on an empty database
                  # mints a new keypair and invalidates every token in flight, with nothing in any log to
                  # say why. The image ships no default for these three and refuses to boot without them.
                  #
                  # SPELLED HERE, AND ONLY HERE. This container is started by compose before any deployer
                  # exists, so the bootstrap creates the role and the database over JDBC and hands the
                  # credential over itself. Every deployment after this one gets the same three variables
                  # from qits-platform-deployments, which reads `resources: postgresql:db` in this
                  # repository's deployments.yml — which is why the run-args line beside this file carries
                  # no datasource env at all.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_platform_idp
                  QITS_RESOURCE_DB_USERNAME: qits_platform_idp
                  QITS_RESOURCE_DB_PASSWORD: "${PG_PLATFORM_IDP_PASSWORD}"
                  # The 'iss' of every token and the base of every endpoint the discovery document advertises.
                  # Spelled here although it equals the shipped default, for the reason every other address in
                  # this file is spelled: an address a deployment inherits silently is one nobody knows to
                  # change. Consumers below carry the same string; a mismatch is rejected at validation.
                  QITS_IDP_ISSUER: ${IDP}
                  # WHICH CLIENTS EXIST. The key REPLACES the shipped list rather than extending it, and an
                  # id that is not on it is unknown — invalid_client, with nothing to say it was a typo. It is
                  # spelled because a client id is a wire alias now, so it moves with the environment name.
                  QITS_IDP_CLIENTS: "${IDP_CLIENTS}"
                  # Generated by this bootstrap, recorded in .qits-bootstrap.env, and handed to the matching
                  # service below. A client without a secret is refused, never open.
                  QITS_IDP_CLIENT_${ENV_KEY}_QITS_CI_SECRET: "${IDP_SECRET_CI}"
                  # qits-artifacts' id carries the tier since the byte-plane split made it an
                  # environment service again. The key embeds the id, so this line moved with it.
                  QITS_IDP_CLIENT_${ENV_KEY}_QITS_ARTIFACTS_SECRET: "${IDP_SECRET_ARTIFACTS}"
                  # Unused in phase 1 (qits-workspaces' agents are phase 2, the gateway's user flows phase 3).
                  # Seeded anyway: the cost is a config line, and the cost of the omission is invalid_client on
                  # a path nobody was looking at.
                  QITS_IDP_CLIENT_${ENV_KEY}_QITS_WORKSPACES_SECRET: "${IDP_SECRET_WORKSPACES}"
                  QITS_IDP_CLIENT_${ENV_KEY}_QITS_GATEWAY_SECRET: "${IDP_SECRET_GATEWAY}"
                  # The audiences each minting client may ask for. Restated in full, because the key replaces
                  # the shipped list rather than extending it — and an audience a client may not ask for is
                  # invalid_target, not a silent bare call. qits-ci is the one client that writes to the
                  # deployer (the build-succeeded intake), and this bootstrap borrows both identities for the
                  # events and the environment calls it makes by hand, so both lists are spelled. The
                  # deployer itself needs no client and no list: it mints nothing, it only validates.
                  QITS_IDP_CLIENT_${ENV_KEY}_QITS_CI_AUDIENCES: "${IDP_AUDIENCES}"
                  QITS_IDP_CLIENT_${ENV_KEY}_QITS_ARTIFACTS_AUDIENCES: "${IDP_AUDIENCES}"
                  # The one wildcard grant, and it is THIS BOOTSTRAP'S now. qits-ci's manual trigger
                  # names no repository, so it demands them all — a token granted project=* — and the
                  # release replays are what present one. The grant used to be the git host's, which
                  # announced every push over HTTP; qits-githost publishes on the bus instead and mints
                  # nothing at all. The idp only states the claim; qits-ci's own enforcement is what
                  # reads '*' as covering every value.
                  QITS_IDP_CLIENT_${ENV_KEY}_QITS_ARTIFACTS_CLAIMS_PROJECT: "*"
                  # WHERE TELEMETRY GOES, and it has to be spelled in every service below. The
                  # images ship the bare qits-observability, and that name died with the
                  # 2026-08-08 rename: observability is an environment service, so its alias
                  # carries the tier. An OTLP exporter dialling a name that does not resolve drops
                  # every trace and every log AND retries, so the whole platform goes dark while
                  # each container fills its own log with the attempts — which is how it was found
                  # on the first prod bootstrap.
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080
                # No volume: /data held the H2 and nothing else, and the image has no mount point for it
                # any more.
                networks: [qits-net]
                restart: unless-stopped

              # THE HOST'S ONE PUBLISHED PORT. Every address this bootstrap dials on 127.0.0.1:${PORT}
              # arrives here first and is handed to the gateway of the environment the request's Host name
              # names — which for a workstation is always the default, because localhost carries no
              # environment label. It serves no paths of its own beyond /q, holds no state and has no client,
              # so the seed needs no volume and no placeholder bundle.
              #
              # In the seed because it is the door: qits-ci and qits-deployments publish no host port, and
              # the CLI reaches both through this process. Without it the first health poll has nothing to
              # ask.
              qits-platform-edge:
                image: qits/platform-edge:latest
                container_name: qits-platform-edge
                ports:
                  - "${PORT}:8080"${EDGE_TLS_PORTS}
                environment:
                  # The whole routing surface: which environments exist, and which one an unlabelled host
                  # (localhost, an IP) resolves to. The default MUST be a member of the list — the process
                  # refuses to start otherwise, rather than letting each request find out.
                  QITS_EDGE_ENVIRONMENTS: ${ENV_NAME}
                  QITS_EDGE_DEFAULT_ENVIRONMENT: ${ENV_NAME}
                  # How an environment name becomes an address. {env} is the only placeholder and this is
                  # the platform's own naming convention, so it equals the shipped default — spelled for the
                  # reason every address here is spelled, and because it is the ONE line that ties the edge
                  # to the wire aliases the rest of this file hands out.
                  QITS_EDGE_UPSTREAM_HOST_PATTERN: "{env}-qits-gateway"
                  QITS_EDGE_UPSTREAM_PORT: "8080"
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${EDGE_TLS}
                networks: [qits-net]
                restart: unless-stopped

              # THE HOST'S SECOND DOOR, and the only one that is not HTTP: the authoritative
              # nameserver for the platform's own names. A registrar delegates a domain to it and the
              # internet reaches it on 53; the record API on 8080 is service-to-service and has no
              # gateway route, deliberately — the gateway proxies HTTP and DNS is not HTTP, so this
              # is a SIBLING of the edge behind the same public IP rather than something behind it.
              #
              # A PLATFORM SERVICE: one delegated nameserver answers for every environment, because a
              # zone is a row. Two of them would be two servers claiming one IP's port 53 and
              # disagreeing about what exists.
              #
              # In the seed because this bootstrap writes to it: with QITS_DOMAIN set the zone row is
              # created over the API in this same run, hours before the pipeline could deploy it.
              # With no domain it runs with no zones at all, which its own README calls a legal state
              # — a server answering REFUSED for everything is what a platform with no public names
              # should have.
              qits-platform-dns:
                image: qits/platform-dns:latest
                container_name: qits-platform-dns
                ports:
                  # BOTH PROTOCOLS. dnsjava drops a whole RRset that will not fit a UDP answer, so a
                  # name with several records answers TC=1 and ZERO records and the client's TCP
                  # retry is the only way it ever gets one. Resolvers also probe TCP outright. The
                  # listener binds 8053 because below 1024 needs privileges this process should not
                  # hold, so the publish is what makes it 53.
                  - "${DNS_PORT}:8053/udp"
                  - "${DNS_PORT}:8053/tcp"
                environment:
                  # SPELLED HERE, AND ONLY HERE, exactly as the idp's and ci's are: compose starts
                  # this container before any deployer exists, so the bootstrap created the role and
                  # the database over JDBC and hands the credential over itself. Every deployment
                  # after this one is handed the same three by qits-platform-deployments, from
                  # `resources: postgresql:db` in this repository's deployments.yml — which is why
                  # the run-args line beside this file carries no datasource env either.
                  #
                  # It REFUSES TO BOOT without them, and for this service that is the failure worth
                  # having: a nameserver that came up on an empty store would answer NXDOMAIN for
                  # every deployed hostname, with nothing anywhere reporting an outage.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_platform_dns
                  QITS_RESOURCE_DB_USERNAME: qits_platform_dns
                  QITS_RESOURCE_DB_PASSWORD: "${PG_PLATFORM_DNS_PASSWORD}"
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080${DNS_IDENTITY}
                # No volume: the store is the postgres below and this service writes nothing that
                # outlives the container.
                networks: [qits-net]
                restart: unless-stopped

              # The platform's PostgreSQL. An ENVIRONMENT service — every tier runs its own — and the
              # deployer's own store, which is why it is in the seed at all: qits-deployments refuses to
              # boot without it, and nothing can deploy a database until the deployer answers.
              #
              # NO depends_on, here or on any consumer, and that is the compose-resurrection rule rather
              # than an omission: on later runs compose starts only the services the deployer does not
              # already manage, and a dependency would resurrect a compose sibling beside its deployed
              # replacement. The cold path is covered by ordering instead — the seed-postgres phase has
              # this server answering before this file is even written — and the warm path by the pair
              # below it: the deployer refuses to boot without its database and `restart: unless-stopped`
              # is the retry loop.
              #
              # No QITS_OBSERVABILITY_URL, deliberately: this is upstream postgres, not an OTLP client,
              # and the variable would be one more thing in `docker inspect` that means nothing.
              ${ENV_NAME}-qits-oci-postgresql:
                image: qits/oci-postgresql:latest
                container_name: ${ENV_NAME}-qits-oci-postgresql
                ports:
                  # For THIS CLI, bound to loopback like the registry port: the bootstrap creates roles
                  # and databases over ordinary JDBC from the host, and it keeps the port after the
                  # deployer replaces this container with its own.
                  - "127.0.0.1:${PG_PORT}:5432"
                environment:
                  # Generated by this bootstrap and recorded in .qits-bootstrap.env BEFORE the server
                  # first started. It applies at initdb only — on a volume that already holds a cluster
                  # this value is ignored, so the recorded one is the only way back in.
                  POSTGRES_PASSWORD: "${PG_SUPERUSER_PASSWORD}"
                volumes:
                  # /var/lib/postgresql, NOT /var/lib/postgresql/data — see the volume's own comment.
                  - qits-oci-postgresql-data:/var/lib/postgresql
                healthcheck:
                  # The database's own answer to "are you serving", and the same command the deployer
                  # gates its cutover with (health_cmd in this repository's deployments.yml). There is no
                  # HTTP endpoint to curl.
                  test: ["CMD-SHELL", "pg_isready -U postgres"]
                  interval: 10s
                  timeout: 5s
                  retries: 30
                networks: [qits-net]
                restart: unless-stopped

              # The deployer, and the topology it decides from: one component, one database, one docker
              # socket. It is the merge-back of qits-cd and qits-serviceregistry, so it stands where both
              # used to. In the seed because the '${ENV_NAME}' environment is created through it minutes
              # from now and because nothing else can start a container. No published host port of its own —
              # the edge and the gateway's /platform-deployments route are the door. Ready at
              # /platform-deployments/q/health/ready.
              #
              # An ENVIRONMENT service: one deployer per tier, deploying its own tier. Its route segment is
              # still /platform-deployments — that names the component, and only the repository was renamed.
              ${ENV_NAME}-qits-deployments:
                image: qits/deployments:latest
                container_name: ${ENV_NAME}-qits-deployments
                group_add: ["${DOCKER_GID}"]
                environment:
                  # ADOPTER #1 of the generic resource contract, and TWO STORES, TWO TRIPLES — the same
                  # shape ci's block below carries and for the same reason. Every application that
                  # declares `resources: postgresql:<name>` is handed
                  # QITS_RESOURCE_<NAME>_URL/_USERNAME/_PASSWORD by this very deployer; its own two
                  # arrive the same way, from the bootstrap rather than from itself. Unset, the binary
                  # refuses to boot at Flyway — which is what makes it safe to have no depends_on: a
                  # deployer that starts before its database simply restarts until the database is
                  # there.
                  #
                  # The role, the database and the username are one identity: qits_deployments.
                  #
                  # The second triple is the OUTBOX of the eventstream library the deployer joined on
                  # 2026-08-10: two Flyway lineages cannot share one database. The library reads the
                  # `eventstream` name in its own shipped defaults, so that spelling is not a choice
                  # made here.
                  #
                  # SPELLED HERE, AND ONLY HERE. Compose starts this container before any deployer
                  # exists, so the bootstrap created both roles and databases over JDBC. Every
                  # deployment after this one is handed the same six variables by a RUNNING deployer,
                  # from `resources: postgresql:db, postgresql:eventstream:qits_deployments_eventstream`
                  # in this repository's deployments.yml — which is why the run-args line beside this
                  # file carries the first triple only, as the deployer's own bootstrap credential, and
                  # never the second.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_deployments
                  QITS_RESOURCE_DB_USERNAME: qits_deployments
                  QITS_RESOURCE_DB_PASSWORD: "${PG_DEPLOYMENTS_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_deployments_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_deployments_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_DEPLOYMENTS_EVENTSTREAM_PASSWORD}"
                  # The event bus, and the same override the seed ci carries one block down: the
                  # eventstream jar's shipped default is the pre-rename `qits-events:8080`, which
                  # resolves to nothing on this network. The deployer SUBSCRIBES durably here — a
                  # BuildSuccessful it never receives is a deployment that never happens — so a wrong
                  # value costs more than a lost publish.
                  QITS_EVENTS_URL: http://${ENV_NAME}-qits-events:8080
                  # Which tier this deployer is, so it can register its own resource row and resolve the
                  # postgres host of an environment application without asking itself first.
                  QITS_ENVIRONMENT: ${ENV_NAME}
                  # THE ADMIN CREDENTIAL, and what makes this component a provisioner rather than only a
                  # consumer: it is what lets it create the role and the database of every application
                  # that declares one. It lives in the same trust domain as the docker socket beside it.
                  QITS_PLATFORM_DEPLOYMENTS_POSTGRES_ADMIN_PASSWORD: "${PG_SUPERUSER_PASSWORD}"
                  # It pulls through the HOST daemon — same reasoning as ci's registry host.
                  QITS_ARTIFACTS_REGISTRY_HOST: localhost:${REGISTRY_PORT}
                  # Per-application run-args live in the qits-deployments-config volume
                  # (config/application.properties, written by the bootstrap), NOT here: a self-update's
                  # successor must inherit them, and env cannot nest those values.
                  # Machine auth, INBOUND ONLY. The build-succeeded intake and the topology writes demand a
                  # bearer addressed to this service; every read stays open. There is no oidc-client and no
                  # secret — the merge removed the peer its ancestor authenticated to.
                  #
                  # THE AUDIENCE IS ITS WIRE ALIAS AND HAS TO BE SPELLED. The shipped default is the old
                  # repository name, so a token minted for ${ENV_NAME}-qits-deployments would be refused by
                  # a service still expecting qits-platform-deployments — 401 on every build-succeeded, on a
                  # gate that looks correctly configured from both sides.
                  QITS_AUTH_MACHINE_AUDIENCE: ${ENV_NAME}-qits-deployments
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP}
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080
                volumes:
                  # No data volume any more: the store is the postgres above, and /data held the H2 files
                  # and nothing else. The config volume stays — it is the run-args a self-update's
                  # successor inherits.
                  - qits-deployments-config:/work/config
                  - /var/run/docker.sock:/var/run/docker.sock
                networks: [qits-net]
                restart: unless-stopped

              # No ports. The gateway is behind the edge now, and an environment service of ${ENV_NAME}
              # rather than a platform one: it was only ever on the platform plane because it bound the
              # host's port, and it does not.
              ${ENV_NAME}-qits-gateway:
                image: qits/gateway:latest
                container_name: ${ENV_NAME}-qits-gateway
                environment:
                  # The route table: an entry is both the on-switch and the target. Every value is a WIRE
                  # ALIAS — this tier's own services carry the tier's name, the platform's four do not.
                  # Aliases of the pipeline-deployed services resolve the moment the deployer cuts them
                  # over; until then those routes 502.
                  # The HOSTED registries, and root-level /v2 with them.
                  QITS_GATEWAY_PROXY_HOSTS_ARTIFACTS: ${ENV_NAME}-qits-artifacts   # also claims root-level /v2 (OCI registry)
                  # THE CACHES, at their OWN segment and nothing else. qits-platform-mirror answers the
                  # store's three prefixes too, and those are deliberately not routed here: two services
                  # cannot share one prefix behind one gateway entry, so third-party traffic picks the
                  # mirror by its own published port and its own client configuration. /mirror is the
                  # service's own segment — its view and its health — and nothing else claims it. A
                  # PLATFORM service, so the alias carries no tier: one cache serves every environment.
                  QITS_GATEWAY_PROXY_HOSTS_MIRROR: qits-platform-mirror
                  QITS_GATEWAY_PROXY_HOSTS_CI: ${ENV_NAME}-qits-ci
                  QITS_GATEWAY_PROXY_HOSTS_PLATFORM_DEPLOYMENTS: ${ENV_NAME}-qits-deployments
                  QITS_GATEWAY_PROXY_HOSTS_OBSERVABILITY: ${ENV_NAME}-qits-observability
                  QITS_GATEWAY_PROXY_HOSTS_PROJECTS: ${ENV_NAME}-qits-projects
                  QITS_GATEWAY_PROXY_HOSTS_WORKSPACES: ${ENV_NAME}-qits-workspaces
                  QITS_GATEWAY_PROXY_HOSTS_STT: ${ENV_NAME}-qits-stt
                  QITS_GATEWAY_PROXY_HOSTS_EVENTS: ${ENV_NAME}-qits-events
                  # The docs reader followed the shelf it reads: qits-docs is an environment service now,
                  # so the host carries the tier — and the KEY moved with the repository, because the
                  # gateway's route SEGMENT did (/platform-docs -> /docs). A segment that is not a known
                  # service is a configuration error caught at the gateway's startup, so this key and the
                  # gateway's own enum have to land in the same release. A key that is MISSING is not an
                  # error: an entry is the on-switch, so absence is a prefix nothing claims and a 404.
                  QITS_GATEWAY_PROXY_HOSTS_DOCS: ${ENV_NAME}-qits-docs
                  # THE GIT HOST, at the segment that names it. /githost carries its view, its API and
                  # its health; the git WIRE PROTOCOL stays at /git, which the gateway carries as a
                  # second prefix on this same entry — every clone url already hardcodes it and git
                  # treats the base as opaque. One entry, two prefixes, one key. This is the entry that
                  # makes QITS_WORKSPACE_GIT_HOST work: a workspace container reaches this platform
                  # through the gateway and through nothing else, so without this line its clone is a
                  # 404 from the tier's own front door.
                  QITS_GATEWAY_PROXY_HOSTS_GITHOST: ${ENV_NAME}-qits-githost
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080
                networks: [qits-net]
                # No depends_on: on later runs compose starts only the services the deployer does not already
                # manage, and a dependency would resurrect a compose sibling next to its deployed replacement.
                restart: unless-stopped

              # THE PLATFORM'S OWN PACKAGES, and nothing third-party: the hosted npm registry, the hosted
              # maven repository, the hosted OCI registry, the daemon binaries and the docs bundles. An
              # ENVIRONMENT service again since the byte-plane split — the pull-through caches below are
              # what made it platform-scoped, and they left.
              ${ENV_NAME}-qits-artifacts:
                image: qits/artifacts:latest
                container_name: ${ENV_NAME}-qits-artifacts
                ports:
                  # For the HOST daemon only: ci publish steps push and the deployer pulls through the host's
                  # docker daemon, which cannot resolve qits-net aliases. localhost:${REGISTRY_PORT} is in
                  # docker's default insecure list, so plain HTTP needs no daemon config.
                  #
                  # The number did not move with the split, deliberately: every pipeline config and every
                  # QITS_ARTIFACTS_REGISTRY_HOST on this platform says ${REGISTRY_PORT}, and what changed is
                  # which service answers behind it. It is published for docker, not for people: the same
                  # service is reachable through the edge at /artifacts like every other route.
                  - "127.0.0.1:${REGISTRY_PORT}:8080"
                environment:
                  QUARKUS_DATASOURCE_ARTIFACTS_JDBC_URL: jdbc:h2:file:/data/artifacts/h2/artifacts
                  QITS_ARTIFACTS_BLOBS_DIR: /data/artifacts/blobs
                  # Machine auth, INBOUND ONLY. The admin writes under /artifacts/api demand a bearer
                  # addressed to this service; every read stays open. There is no oidc-client and no
                  # secret any more: the one thing this service ever minted a token for was the git
                  # host's post-receive announcement, and the git host is qits-githost now — which
                  # publishes on the bus and mints nothing.
                  #
                  # THE AUDIENCE HAS TO BE SPELLED, and that is new with the split: the image ships the
                  # bare qits-platform-artifacts, and this service's alias carries the tier now. A token
                  # minted for ${ENV_NAME}-qits-artifacts would be refused by a service still validating
                  # the old name — 401 on every admin write, on a gate that looks right from both sides.
                  QITS_AUTH_MACHINE_AUDIENCE: ${ENV_NAME}-qits-artifacts
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP}
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080
                volumes:
                  - qits-artifacts-data:/data
                networks: [qits-net]
                restart: unless-stopped

              # EVERYTHING THIRD-PARTY A BUILD RESOLVES, cached: npmjs, Maven Central, Docker Hub, quay.io
              # and the Red Hat registry, each behind a pull-through cache with its own eviction window.
              #
              # A PLATFORM service, and the only byte service that is: a cache of Maven Central is one
              # cache for a machine however many tiers run on it. That was qits-platform-artifacts' only
              # reason to be platform-scoped, and this is what is left of it.
              #
              # In the seed because everything else is downstream of it. Every seed publish resolves its
              # third-party dependencies here, every image build pulls its base layers here, and a cache
              # that is not up yet is not a slow build but a failed one. It starts COLD and warms up: the
              # first of each fetch pays the upstream, and nothing has to be pre-loaded.
              qits-platform-mirror:
                image: qits/platform-mirror:latest
                container_name: qits-platform-mirror
                ports:
                  # THE THIRD-PARTY DOOR, for the HOST's docker daemon — the same consumer the registry
                  # port above exists for, and the reason this is a second PORT rather than a path: both
                  # services answer the literal prefixes /artifacts/npm, /artifacts/maven and /v2, so the
                  # client's configuration is what picks between them. dockerd's registry-mirrors names
                  # this one; a pipeline's QITS_REGISTRY names the other.
                  - "127.0.0.1:${MIRROR_PORT}:8080"
                environment:
                  # SPELLED HERE, AND ONLY HERE, exactly as the idp's and the bus's are: compose starts
                  # this container before any deployer exists, so the bootstrap created the role and the
                  # database over JDBC and hands the credential over itself. Every deployment after this
                  # one is handed the same three by qits-platform-deployments, from `resources:
                  # postgresql:db` in this repository's deployments.yml — which is why the run-args line
                  # beside this file carries no datasource env either.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_platform_mirror
                  QITS_RESOURCE_DB_USERNAME: qits_platform_mirror
                  QITS_RESOURCE_DB_PASSWORD: "${PG_PLATFORM_MIRROR_PASSWORD}"
                  # WHERE THE CACHED BYTES LAND, and it has to be spelled: the jar's default is under
                  # ${user.home}, which this image's passwd-less UID resolves to the literal "?" — the
                  # process comes up and writes its cache into a directory nobody can find.
                  QITS_ARTIFACTS_BLOBS_DIR: /data/mirror/blobs
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080
                volumes:
                  - qits-platform-mirror-data:/data
                networks: [qits-net]
                restart: unless-stopped

              # THE GIT HOST. A service of its own since the byte-plane split: a repository was never an
              # artifact, it only shared the storage — packs, pack indexes and reftables are ordinary
              # content-addressed blobs, which is why this service needs a store and not a directory.
              #
              # An ENVIRONMENT service, because every one of its consumers already was one: qits-ci,
              # qits-projects, qits-workspaces, the daemons and the workspace containers.
              #
              # In the seed because the first push of this boot goes to it. Nothing can be built out of a
              # repository nothing hosts, and every repository this platform has is created here minutes
              # from now.
              ${ENV_NAME}-qits-githost:
                image: qits/githost:latest
                container_name: ${ENV_NAME}-qits-githost
                ports:
                  # THE HOST-SIDE GIT DOOR, and the one thing the split would otherwise have closed. A
                  # person clones and pushes from the workstation, which is not on qits-net; the clone url
                  # used to be localhost:${REGISTRY_PORT}/artifacts/git/<repo> and rode the registry's
                  # port. It is localhost:${GIT_HOST_PORT}/git/<repo> now.
                  #
                  # This bootstrap does not use it: every phase that pushes runs inside a container that
                  # joined qits-net, so it dials the alias like every other member.
                  - "127.0.0.1:${GIT_HOST_PORT}:8080"
                environment:
                  # TWO STORES, TWO TRIPLES, the same shape ci's block carries and for the same reason:
                  # this service's own pack catalog and the outbox of the eventstream library are two
                  # Flyway lineages and cannot share one database. The library reads the `eventstream`
                  # name in its own shipped defaults, so that spelling is not a choice made here.
                  #
                  # SPELLED HERE, AND ONLY HERE: compose starts this container before any deployer
                  # exists. Later deployments are handed the same six by qits-platform-deployments from
                  # `resources: postgresql:db, postgresql:eventstream:qits_githost_eventstream`.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_githost
                  QITS_RESOURCE_DB_USERNAME: qits_githost
                  QITS_RESOURCE_DB_PASSWORD: "${PG_GITHOST_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_githost_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_githost_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_GITHOST_EVENTSTREAM_PASSWORD}"
                  # WHERE THE REPOSITORIES LIVE, and it has to be spelled for the reason the mirror's is:
                  # the jar's default sits under ${user.home}, which this image's passwd-less UID cannot
                  # resolve.
                  QITS_ARTIFACTS_BLOBS_DIR: /data/githost/blobs
                  # WHAT A PUSH BECOMES. SCMPublishCommit, SCMPublishTag and the two deletes go through
                  # the eventstream outbox to the bus, where qits-ci's durable listener turns a commit
                  # into a run and qits-projects' turns it into a backup. It REPLACES the post-receive
                  # HTTP fan-out, which retried in memory for three minutes and then lost the event —
                  # twice on this platform, both times during a consumer's redeploy. The jar's shipped
                  # default is the pre-rename qits-events:8080, which resolves to nothing here.
                  QITS_EVENTS_URL: http://${ENV_NAME}-qits-events:8080
                  # What turns /git/:projectId/:repoName into a repo id, and therefore what makes a
                  # committed relative submodule url (../<name>.git) resolve natively. Unset, the
                  # name-addressed scheme 404s and every project agent starts with an empty /workspace.
                  QITS_PROJECTS_NAME_RESOLVER_URL: http://${ENV_NAME}-qits-projects:8080/projects/api/projects
                  # The default branch's escape hatch: a push carrying -o qits.token=<this> is let through
                  # even when protection is on. Unset would mean no value matches and nothing overrides —
                  # which is the shipped default, and which this bootstrap cannot live with (it pushes
                  # main many times before a release endpoint exists to go through).
                  QITS_REPOSITORIES_GIT_PUSH_TOKEN: "${PUSH_TOKEN}"
                  # Protection stays ON: the bootstrap's own pushes carry the token above, and a rerun
                  # that silently disarmed the seatbelt would be the quiet failure. The service ships it
                  # FALSE, because it is the git host that serves its own redeploy.
                  QITS_REPOSITORIES_GIT_PROTECT_DEFAULT_BRANCH: "true"
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080
                volumes:
                  - qits-githost-data:/data
                networks: [qits-net]
                restart: unless-stopped

              ${ENV_NAME}-qits-ci:
                image: qits/ci:latest
                container_name: ${ENV_NAME}-qits-ci
                # Unprivileged uid stays; the socket group is all it needs.
                group_add: ["${DOCKER_GID}"]
                environment:
                  # TWO STORES, TWO TRIPLES. ci's own database and the outbox of the eventstream library
                  # it joins are two Flyway lineages and cannot share one. The library reads the
                  # `eventstream` name in its own shipped defaults, so the second triple's spelling is
                  # not a choice made here. Its file-H2 predecessor sat under ${user.home}, which a
                  # container has not got — that is gone with the H2.
                  #
                  # SPELLED HERE, AND ONLY HERE, for the same reason as the idp's above: compose starts
                  # this container before any deployer exists. Later deployments are handed the same six
                  # variables by qits-platform-deployments, from
                  # `resources: postgresql:db, postgresql:eventstream:qits_ci_eventstream` in this
                  # repository's deployments.yml.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_ci
                  QITS_RESOURCE_DB_USERNAME: qits_ci
                  QITS_RESOURCE_DB_PASSWORD: "${PG_CI_PASSWORD}"
                  QITS_RESOURCE_EVENTSTREAM_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_ci_eventstream
                  QITS_RESOURCE_EVENTSTREAM_USERNAME: qits_ci_eventstream
                  QITS_RESOURCE_EVENTSTREAM_PASSWORD: "${PG_CI_EVENTSTREAM_PASSWORD}"
                  # ci's own fetch of the pushed ref, and the same base as seen from inside a step
                  # container — steps join qits-net, so both resolve the git host directly.
                  #
                  # THE GIT HOST'S ROOT, WITH NO PATH: ci appends /git/<repoId> itself. It used to be
                  # /artifacts, because the routes lived inside the artifacts store; qits-githost serves
                  # /git at its own root and there is nothing in front of it.
                  QITS_CI_GIT_HOST_URL: http://${ENV_NAME}-qits-githost:8080
                  QITS_CI_CONTAINER_GIT_URL: http://${ENV_NAME}-qits-githost:8080
                  # The network step containers join. Still qits-net: it is the deployer's legacy network,
                  # the one every container on this host is on whatever plane it belongs to.
                  QITS_CI_NETWORK: qits-net
                  # NO QITS_PLATFORM_DEPLOYMENTS_INTAKE_URL. ci's direct POST to the deployer was retired
                  # on 2026-08-10: a green build is announced on the BUS now, ci -> outbox ->
                  # ${ENV_NAME}-qits-events -> the deployer's durable subscriber. qits-ci reads no such key
                  # any more, and a value nothing reads is a lie waiting to age. The deployer's HTTP intake
                  # stays as the manual door — this bootstrap's own build-event replay uses it.
                  # Injected into publish steps as QITS_REGISTRY: dialled by the HOST daemon (see the
                  # qits-artifacts ports note). The HOSTED registry, never the mirror: a publish step
                  # pushes the platform's own image, and the mirror takes no writes at all.
                  QITS_ARTIFACTS_REGISTRY_HOST: localhost:${REGISTRY_PORT}
                  # THE FOUR ROOTS EVERY STEP CONTAINER IS HANDED, and the byte-plane split is why they are
                  # spelled here at all. ci ships them defaulted to qits-platform-artifacts:8080, one
                  # service that answered for hosted packages and cached ones alike; there are two services
                  # now and the split runs straight through this block:
                  #
                  #   hosted npm, maven and docs  -> this tier's qits-artifacts
                  #   the npmjs cache             -> qits-platform-mirror, the platform's one cache
                  #
                  # They are dialled by the STEP CONTAINER ITSELF over qits-net, so these are wire aliases
                  # and NOT the localhost mapping above — a step container has no localhost:${REGISTRY_PORT}.
                  QITS_ARTIFACTS_NPM_HOSTED_URL: http://${ENV_NAME}-qits-artifacts:8080/artifacts/npm/npm/
                  QITS_ARTIFACTS_NPM_PROXY_URL: http://qits-platform-mirror:8080/artifacts/npm/npmjs/
                  QITS_ARTIFACTS_MAVEN_REGISTRY_URL: http://${ENV_NAME}-qits-artifacts:8080/artifacts/maven/maven
                  QITS_ARTIFACTS_DOCS_URL: http://${ENV_NAME}-qits-artifacts:8080/artifacts/docs/docs
                  # The websocket a step container's daemon dials BACK to this service. The image ships the
                  # unqualified ws://qits-ci:8080/ci/daemon, and nothing by that alias exists any more — a
                  # blank here fails every step with "could not reach qits-ci", which is exactly how it was
                  # found on the first prod bootstrap.
                  QITS_CI_CONTAINER_DAEMON_URL: ws://${ENV_NAME}-qits-ci:8080/ci/daemon
                  # Same class of self-name: the release train asks workspaces for version identity.
                  QITS_CI_WORKSPACES_URL: http://${ENV_NAME}-qits-workspaces:8080
                  # The event bus. The eventstream jar's shipped default is the pre-rename
                  # `qits-events:8080`, which resolves to nothing on this network — measured: every
                  # outbox delivery of the seed ci dialled it, got ConnectException, and gave up
                  # after its five attempts. The deployed ci gets this same value from its run-args;
                  # the seed has to be told here, like every other wire name in this block.
                  QITS_EVENTS_URL: http://${ENV_NAME}-qits-events:8080
                  # The binary every step container downloads and execs — uploaded by this bootstrap, digest
                  # pinned. Blank would mean every run fails as never-registered.
                  QITS_CI_DAEMON_VERSION: "${DAEMON_SHA}"
                  # Where a step container wgets that binary. The shipped default still names the
                  # retired qits-platform-artifacts alias; on qits-net the store is this tier's.
                  QITS_CI_DAEMON_BINARY_URL_TEMPLATE: "http://${ENV_NAME}-qits-artifacts:8080/artifacts/daemons/qits-ci-daemon/{version}"
                  # Machine auth. Inbound: /ci/api/events/* demands a bearer addressed to this service whose
                  # project claim covers the event's repo. Outbound: the build-succeeded notify to the
                  # deployer carries one.
                  #
                  # THE AUDIENCE IS ITS WIRE ALIAS AND HAS TO BE SPELLED, for the same reason the deployer's
                  # is: the image ships the unqualified qits-ci, and the idp mints ${ENV_NAME}-qits-ci.
                  QITS_AUTH_MACHINE_AUDIENCE: ${ENV_NAME}-qits-ci
                  QITS_AUTH_MACHINE_REQUIRED: "${MACHINE_REQUIRED}"
                  QUARKUS_OIDC_AUTH_SERVER_URL: ${IDP}
                  QUARKUS_OIDC_CLIENT_CLIENT_ENABLED: "${MACHINE_CLIENT}"
                  QUARKUS_OIDC_CLIENT_AUTH_SERVER_URL: ${IDP}
                  # The client id and the audience it asks for are BOTH this tier's aliases, and the image
                  # ships the unqualified pair (qits-ci asking for qits-platform-deployments). Either one
                  # left alone is a token request the idp refuses — invalid_client for the first,
                  # invalid_target for the second — on a notify that is swallowed at debug.
                  QUARKUS_OIDC_CLIENT_CLIENT_ID: ${ENV_NAME}-qits-ci
                  QUARKUS_OIDC_CLIENT_GRANT_OPTIONS_CLIENT_AUDIENCE: ${ENV_NAME}-qits-deployments
                  QUARKUS_OIDC_CLIENT_CREDENTIALS_SECRET: "${IDP_SECRET_CI}"
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080
                volumes:
                  # The socket and nothing else. ci's /data held the H2 files, and before that a bare git
                  # mirror per repository — it reads pipeline config off the git host's content routes
                  # now, so the image has no /data at all and this container writes nothing that outlives
                  # it. The socket stays: starting a step container is what this service does.
                  - /var/run/docker.sock:/var/run/docker.sock
                networks: [qits-net]
                restart: unless-stopped

              # THE BUS, and last in this file because everything above publishes to it or subscribes to
              # it. In the seed since 2026-08-10, when ci's direct POST to the deployer was retired: a
              # green build now travels ci -> outbox -> here -> the deployer's durable subscriber, and
              # every hop of that chain has to exist before the FIRST deployment of a cold boot. The
              # pipeline deploys it too, at its ordinary place in the train — the seed is only what
              # carries the first six deployments, which used to announce into nothing.
              #
              # An ENVIRONMENT service, so the container name is this tier's alias — which is also what
              # the two blocks above dial as QITS_EVENTS_URL, and what the deployer searches for when it
              # adopts this container's successor at cutover.
              ${ENV_NAME}-qits-events:
                image: qits/events:latest
                container_name: ${ENV_NAME}-qits-events
                environment:
                  # SPELLED HERE, AND ONLY HERE, exactly as ci's, the idp's and the nameserver's are:
                  # compose starts this container before any deployer exists, so the bootstrap created
                  # the role and the database over JDBC and hands the credential over itself. Every
                  # deployment after this one is handed the same three by qits-platform-deployments, from
                  # `resources: postgresql:db` in this repository's deployments.yml — which is why the
                  # run-args line beside this file carries no datasource env either.
                  #
                  # The database name is the deployer's own default derivation, not a choice made here:
                  # the application name with `qits-` dropped, dashes underscored, under `qits_`. So the
                  # row the deployer registers on the first pipeline deployment is the row this creates.
                  #
                  # It REFUSES TO BOOT without them — the events jar's datasource is an expression over
                  # these three with no fallback URL — and for the bus that is the failure worth having:
                  # a bus that came up storing nothing would swallow every announcement silently.
                  QITS_RESOURCE_DB_URL: jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_events
                  QITS_RESOURCE_DB_USERNAME: qits_events
                  QITS_RESOURCE_DB_PASSWORD: "${PG_EVENTS_PASSWORD}"
                  QITS_OBSERVABILITY_URL: http://${ENV_NAME}-qits-observability:8080
                # No volume: the store is the postgres above, /data held the H2 and nothing else, and the
                # image has no mount point left for it.
                #
                # No machine auth: this service enforces none, which is why its run-args line carries
                # none either. Publishing to the bus is an ordinary PUT from qits-net.
                networks: [qits-net]
                restart: unless-stopped
            """;

    private static final String RUN_ARGS = """
            # Generated by qits-cli-bootstrap — qits.platform.deployments.run-args.<application>: what each deployed container
            # needs beyond its image. Whitespace-split, appended verbatim between the deployer's flags and the
            # image. The namespace was qits.cd.run-args before the merge-back; a deployment carrying the old
            # spelling configures nothing.
            #
            # An <application> is a REPOSITORY NAME, and six of them were renamed on 2026-08-08: a line under
            # a retired name configures nothing and the deployment comes up with no volumes and no env, which
            # is a container that boots, passes health and has lost its database.
            #
            # Every hostname in every value below is a WIRE ALIAS: ${ENV_NAME}-qits-<app> for a service of
            # this environment, the bare repository name for one of the four platform services.
            #
            # NO LINE BELOW CARRIES A DATASOURCE, with two exceptions that say why on themselves:
            # qits-artifacts, the one service still on a file H2, and qits-deployments, whose
            # own store is the one credential the bootstrap issues and the deployer then registers as
            # its own. Every other store is DECLARED rather than configured: a
            # repository writes `resources: postgresql:<name>` in its .config/qits/deployments.yml, and
            # qits-platform-deployments creates the role and the database on this tier's postgres and
            # injects QITS_RESOURCE_<NAME>_URL / _USERNAME / _PASSWORD before the container starts. Those
            # variables are injected BEFORE the arguments here, and docker keeps the last -e — so a
            # datasource line here is an operator PIN that outlives a password rotation and breaks the
            # deployment it looks like it is configuring. The seed compose file spells the triples for
            # qits-ci, qits-platform-idp, qits-platform-dns, qits-events and the deployer's OWN OUTBOX
            # for the one reason that does not apply here: it starts them before any deployer exists.
            #
            # EVERY LINE OF A QITS APPLICATION CARRIES QITS_OBSERVABILITY_URL, for the same reason the seed
            # compose spells it on every service: the images ship the bare qits-observability, and that
            # name died with the 2026-08-08 rename. An OTLP exporter dialling a name that does not resolve
            # drops every trace and every log AND retries, so the platform goes dark while each container
            # fills its own log with the attempts. qits-oci-postgresql is the one exception and says so on
            # its own line: it is upstream postgres, which has no exporter to point anywhere.
            #
            # WHERE THE DEPLOYER READS A DEPLOYMENT SPEC — a plain property, not a run-args line, because
            # this file is the deployer's own configuration. The image still ships the pre-split
            # qits-platform-artifacts, a name that resolves to nothing; the spec read is how a green build
            # becomes a deployment, so a deployer without this line deploys nothing and says only "timeout".
            qits.platform.deployments.git-host-url=http://${ENV_NAME}-qits-githost:8080
            # THE HOST PORT IS THE EDGE'S. qits-gateway carries no -p at all any more; publishing it from two
            # applications is a bind conflict that only shows up on the second cutover.
            ${EDGE_TLS_NOTE}qits.platform.deployments.run-args.qits-platform-edge=-p ${PORT}:8080${EDGE_TLS_ARGS} -e QITS_EDGE_ENVIRONMENTS=${ENV_NAME} -e QITS_EDGE_DEFAULT_ENVIRONMENT=${ENV_NAME} -e QITS_EDGE_UPSTREAM_HOST_PATTERN={env}-qits-gateway -e QITS_EDGE_UPSTREAM_PORT=8080 -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            qits.platform.deployments.run-args.qits-gateway=-e QITS_GATEWAY_PROXY_HOSTS_ARTIFACTS=${ENV_NAME}-qits-artifacts -e QITS_GATEWAY_PROXY_HOSTS_MIRROR=qits-platform-mirror -e QITS_GATEWAY_PROXY_HOSTS_CI=${ENV_NAME}-qits-ci -e QITS_GATEWAY_PROXY_HOSTS_PLATFORM_DEPLOYMENTS=${ENV_NAME}-qits-deployments -e QITS_GATEWAY_PROXY_HOSTS_OBSERVABILITY=${ENV_NAME}-qits-observability -e QITS_GATEWAY_PROXY_HOSTS_PROJECTS=${ENV_NAME}-qits-projects -e QITS_GATEWAY_PROXY_HOSTS_WORKSPACES=${ENV_NAME}-qits-workspaces -e QITS_GATEWAY_PROXY_HOSTS_STT=${ENV_NAME}-qits-stt -e QITS_GATEWAY_PROXY_HOSTS_EVENTS=${ENV_NAME}-qits-events -e QITS_GATEWAY_PROXY_HOSTS_DOCS=${ENV_NAME}-qits-docs -e QITS_GATEWAY_PROXY_HOSTS_GITHOST=${ENV_NAME}-qits-githost -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # THE HOSTED HALF OF THE BYTE PLANE, and the one deployment here still carrying a file
            # database: /data is the H2 and the blob store both, which is why the volume stays.
            #
            # QITS_AUTH_MACHINE_AUDIENCE is new and is not decoration. The image ships the bare
            # qits-platform-artifacts, and the byte-plane split made this an environment service whose
            # alias carries the tier — an unspelled audience is a 401 on every admin write.
            #
            # GONE WITH THE SPLIT, and each absence is a service that owns it now:
            #   QITS_REPOSITORIES_GIT_*      the git host is qits-githost, four lines down.
            #   QITS_CI_INTAKE_URL           there is no post-receive HTTP fan-out; pushes are events.
            #   QITS_PROJECTS_*              both were the git host's dials and went with it.
            #   QUARKUS_OIDC_CLIENT_*        this service mints nothing any more. The announcement was
            #                                the only thing it ever held a token for.
            #
            # The two GC pin sources stay: a pin source that cannot be reached makes the sweep abort
            # fail-closed rather than delete a live artifact — so every sweep stops and the cleanup banner
            # hangs on its timeout instead.
            qits.platform.deployments.run-args.qits-artifacts=-p 127.0.0.1:${REGISTRY_PORT}:8080 -v qits-artifacts-data:/data -e QUARKUS_DATASOURCE_ARTIFACTS_JDBC_URL=jdbc:h2:file:/data/artifacts/h2/artifacts -e QITS_ARTIFACTS_BLOBS_DIR=/data/artifacts/blobs -e QITS_AUTH_MACHINE_AUDIENCE=${ENV_NAME}-qits-artifacts -e QITS_AUTH_MACHINE_REQUIRED=${MACHINE_REQUIRED} -e QUARKUS_OIDC_AUTH_SERVER_URL=${IDP} -e QITS_ARTIFACTS_GC_PINS_CD_BASE_URL=http://${ENV_NAME}-qits-deployments:8080/platform-deployments/api -e QITS_ARTIFACTS_GC_PINS_CI_BASE_URL=http://${ENV_NAME}-qits-ci:8080/ci/api -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # THE CACHE HALF. One published port, one volume, one address to say — and no datasource,
            # because `resources: postgresql:db` in its own deployments.yml is what gets it a store and the
            # deployer injects the triple before the successor starts. The seed compose block spells that
            # triple for the one reason that does not apply here: it starts this container before any
            # deployer exists.
            #
            # No machine auth of any kind: this service serves cached third-party bytes to anonymous
            # clients and mints nothing, so it holds no client and validates no audience. The blobs dir is
            # spelled because the jar's default sits under ${user.home}, which this image's passwd-less UID
            # resolves to the literal "?".
            qits.platform.deployments.run-args.qits-platform-mirror=-p 127.0.0.1:${MIRROR_PORT}:8080 -v qits-platform-mirror-data:/data -e QITS_ARTIFACTS_BLOBS_DIR=/data/mirror/blobs -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # THE GIT HOST. The published port is the door a PERSON pushes through — the workstation is not
            # on qits-net, and the clone url moved from localhost:${REGISTRY_PORT}/artifacts/git/<repo> to
            # localhost:${GIT_HOST_PORT}/git/<repo> when the routes left the artifacts store. A -p missing
            # here is that door closing at the first cutover.
            #
            # NO DATASOURCE ENV: both stores are declared (`resources: postgresql:db,
            # postgresql:eventstream:qits_githost_eventstream`) and injected by the deployer. The volume
            # stays, because a repository's packs and reftables are blobs on it.
            #
            # QITS_EVENTS_URL is what makes a push visible to the platform at all: SCMPublishCommit,
            # SCMPublishTag and the two deletes ride the outbox to the bus, where ci's listener queues the
            # run. The eventstream jar's baked default is the pre-rename qits-events:8080.
            qits.platform.deployments.run-args.qits-githost=-p 127.0.0.1:${GIT_HOST_PORT}:8080 -v qits-githost-data:/data -e QITS_ARTIFACTS_BLOBS_DIR=/data/githost/blobs -e QITS_EVENTS_URL=http://${ENV_NAME}-qits-events:8080 -e QITS_PROJECTS_NAME_RESOLVER_URL=http://${ENV_NAME}-qits-projects:8080/projects/api/projects -e QITS_REPOSITORIES_GIT_PUSH_TOKEN=${PUSH_TOKEN} -e QITS_REPOSITORIES_GIT_PROTECT_DEFAULT_BRANCH=true -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # THE FOUR STEP-CONTAINER ROOTS, split across the two byte services exactly as the seed block
            # above splits them: hosted npm, maven and docs at this tier's qits-artifacts, the npmjs cache
            # at qits-platform-mirror. ci's shipped defaults all name qits-platform-artifacts:8080, which
            # resolves to nothing — and the failure is a step that cannot install a dependency, not a
            # deployment that refuses to start.
            #
            # NO QITS_PLATFORM_DEPLOYMENTS_INTAKE_URL. ci's direct POST to the deployer was retired on
            # 2026-08-10 and the key it read is gone with it: a green build is announced on the bus,
            # ci -> outbox -> ${ENV_NAME}-qits-events -> the deployer's durable subscriber, which is what
            # QITS_EVENTS_URL below configures. A line naming a key nothing reads outlives the reader.
            # QITS_AUTH_MACHINE_AUDIENCE and QUARKUS_OIDC_CLIENT_CLIENT_ID are both this tier's alias: ci
            # ships the unqualified qits-ci for each, and the idp knows neither name.
            #
            # NO DATASOURCE ENV, AND NO DATA VOLUME — and the asymmetry with the seed compose block is
            # deliberate. ci's deployments.yml declares
            # `resources: postgresql:db, postgresql:eventstream:qits_ci_eventstream`, so the deployer
            # creates both databases before the successor container starts and injects the six
            # QITS_RESOURCE_* variables itself, from the registry row that holds the current password.
            # A line here would be an operator PIN — run-args are appended after the injected env and
            # docker keeps the last -e — so it would survive the deployer rotating that password and
            # break the deployment it looks like it is configuring. The seed block spells the same
            # variables because at that moment no deployer exists to inject anything. The /data volume
            # went with the H2: the image has no mount point for it any more.
            qits.platform.deployments.run-args.qits-ci=-v /var/run/docker.sock:/var/run/docker.sock --group-add ${DOCKER_GID} -e QITS_CI_GIT_HOST_URL=http://${ENV_NAME}-qits-githost:8080 -e QITS_CI_CONTAINER_GIT_URL=http://${ENV_NAME}-qits-githost:8080 -e QITS_CI_NETWORK=qits-net -e QITS_ARTIFACTS_REGISTRY_HOST=localhost:${REGISTRY_PORT} -e QITS_ARTIFACTS_NPM_HOSTED_URL=http://${ENV_NAME}-qits-artifacts:8080/artifacts/npm/npm/ -e QITS_ARTIFACTS_NPM_PROXY_URL=http://qits-platform-mirror:8080/artifacts/npm/npmjs/ -e QITS_ARTIFACTS_MAVEN_REGISTRY_URL=http://${ENV_NAME}-qits-artifacts:8080/artifacts/maven/maven -e QITS_ARTIFACTS_DOCS_URL=http://${ENV_NAME}-qits-artifacts:8080/artifacts/docs/docs -e QITS_CI_DAEMON_VERSION=${DAEMON_SHA} -e QITS_CI_DAEMON_BINARY_URL_TEMPLATE=http://${ENV_NAME}-qits-artifacts:8080/artifacts/daemons/qits-ci-daemon/{version} -e QITS_CI_CONTAINER_DAEMON_URL=ws://${ENV_NAME}-qits-ci:8080/ci/daemon -e QITS_CI_WORKSPACES_URL=http://${ENV_NAME}-qits-workspaces:8080 -e QITS_EVENTS_URL=http://${ENV_NAME}-qits-events:8080 -e QITS_AUTH_MACHINE_AUDIENCE=${ENV_NAME}-qits-ci -e QITS_AUTH_MACHINE_REQUIRED=${MACHINE_REQUIRED} -e QUARKUS_OIDC_AUTH_SERVER_URL=${IDP} -e QUARKUS_OIDC_CLIENT_CLIENT_ENABLED=${MACHINE_CLIENT} -e QUARKUS_OIDC_CLIENT_AUTH_SERVER_URL=${IDP} -e QUARKUS_OIDC_CLIENT_CLIENT_ID=${ENV_NAME}-qits-ci -e QUARKUS_OIDC_CLIENT_GRANT_OPTIONS_CLIENT_AUDIENCE=${ENV_NAME}-qits-deployments -e QUARKUS_OIDC_CLIENT_CREDENTIALS_SECRET=${IDP_SECRET_CI} -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # The platform's PostgreSQL, deployed like everything else. The host publish is kept so this
            # CLI can reconnect to the same server after the deployer replaces the seed container with its
            # own — the seed's port would otherwise go with the seed. The mount path is
            # /var/lib/postgresql and not /var/lib/postgresql/data: postgres 18 keeps PGDATA at
            # /var/lib/postgresql/18/docker, and the old path mounts the volume BESIDE the cluster, which
            # writes every byte into the container layer and loses it on the next recreate.
            #
            # POSTGRES_PASSWORD applies at initdb only, so on this cutover it is inert — the volume
            # already holds an initialised cluster. It is spelled anyway, because the run-args are also
            # what a cold deployment on a fresh volume would use. One superuser password for the whole
            # platform until there is per-tier configuration to hold more than one.
            qits.platform.deployments.run-args.qits-oci-postgresql=-p 127.0.0.1:${PG_PORT}:5432 -v qits-oci-postgresql-data:/var/lib/postgresql -e POSTGRES_PASSWORD=${PG_SUPERUSER_PASSWORD}
            # The deployer's own deployment — the self-update handoff. Two mounts and a socket, all
            # load-bearing: the config volume holds this very file so the successor inherits every line of
            # it, and the docker socket is what makes it a deployer at all. There is no data volume: the
            # topology, the deployment history and the resource credentials live in postgres now, and the
            # QITS_RESOURCE_DB_* triple is how this component consumes the same contract it hands every
            # other application. QITS_PLATFORM_DEPLOYMENTS_POSTGRES_ADMIN_PASSWORD is what lets it
            # provision one. Machine auth INBOUND only: it validates qits-ci's bearer and mints nothing, so
            # no oidc-client and no secret — but the audience it validates AGAINST is this tier's alias, and
            # the image still ships the pre-rename repository name.
            #
            # ONE TRIPLE, NOT TWO, and the asymmetry with the seed compose block is the point. The
            # deployer's OUTBOX is declared — `postgresql:eventstream:qits_deployments_eventstream` in
            # its own deployments.yml — so a RUNNING deployer provisions it for its successor and
            # injects the triple from the registry row that holds the current password. Pinning it here
            # would be an operator pin that outlives the next rotation. QITS_RESOURCE_DB_* stays because
            # it is the ONE credential nothing else can issue: the deployer's own store is what the
            # bootstrap hands it and the deployer then registers as its own.
            #
            # QITS_EVENTS_URL is the wire-name override and belongs here, not in the resources: the
            # eventstream jar's baked default is the pre-rename `qits-events:8080`, and this deployer
            # SUBSCRIBES — a BuildSuccessful it never receives is a deployment that never happens.
            qits.platform.deployments.run-args.qits-deployments=-v qits-deployments-config:/work/config -v /var/run/docker.sock:/var/run/docker.sock --group-add ${DOCKER_GID} -e QITS_RESOURCE_DB_URL=jdbc:postgresql://${ENV_NAME}-qits-oci-postgresql:5432/qits_deployments -e QITS_RESOURCE_DB_USERNAME=qits_deployments -e QITS_RESOURCE_DB_PASSWORD=${PG_DEPLOYMENTS_PASSWORD} -e QITS_ENVIRONMENT=${ENV_NAME} -e QITS_PLATFORM_DEPLOYMENTS_POSTGRES_ADMIN_PASSWORD=${PG_SUPERUSER_PASSWORD} -e QITS_ARTIFACTS_REGISTRY_HOST=localhost:${REGISTRY_PORT} -e QITS_EVENTS_URL=http://${ENV_NAME}-qits-events:8080 -e QITS_AUTH_MACHINE_AUDIENCE=${ENV_NAME}-qits-deployments -e QITS_AUTH_MACHINE_REQUIRED=${MACHINE_REQUIRED} -e QUARKUS_OIDC_AUTH_SERVER_URL=${IDP} -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # The idp's own deployment. NO DATASOURCE ENV AND NO VOLUME: `resources: postgresql:db` in its
            # deployments.yml is what gets it a store, and the deployer injects the triple from the
            # registry row before the successor starts. That row is what keeps the SIGNING KEY across
            # deployments — a redeploy landing on a fresh database mints a new keypair and invalidates
            # every token in flight — and pinning the triple here would outlive a rotation and break it.
            # The seed compose block spells the same three variables because it starts the idp before any
            # deployer exists. /data held the H2 and nothing else, so the volume went with it.
            # The claims grant is the wildcard this bootstrap's own release replays present: qits-ci's
            # manual trigger names no repository, so it demands them all. It used to be the git host's,
            # which announced every push over HTTP; qits-githost publishes on the bus and mints nothing.
            # QITS_IDP_CLIENTS and both audience lists are restated in full, because each key REPLACES the
            # shipped list rather than extending it — and every id in them is a wire alias, so they move with
            # the environment name while the image's defaults cannot.
            qits.platform.deployments.run-args.qits-platform-idp=-e QITS_IDP_ISSUER=${IDP} -e QITS_IDP_CLIENTS=${IDP_CLIENTS} -e QITS_IDP_CLIENT_${ENV_KEY}_QITS_CI_SECRET=${IDP_SECRET_CI} -e QITS_IDP_CLIENT_${ENV_KEY}_QITS_ARTIFACTS_SECRET=${IDP_SECRET_ARTIFACTS} -e QITS_IDP_CLIENT_${ENV_KEY}_QITS_WORKSPACES_SECRET=${IDP_SECRET_WORKSPACES} -e QITS_IDP_CLIENT_${ENV_KEY}_QITS_GATEWAY_SECRET=${IDP_SECRET_GATEWAY} -e QITS_IDP_CLIENT_${ENV_KEY}_QITS_CI_AUDIENCES=${IDP_AUDIENCES} -e QITS_IDP_CLIENT_${ENV_KEY}_QITS_ARTIFACTS_AUDIENCES=${IDP_AUDIENCES} -e QITS_IDP_CLIENT_${ENV_KEY}_QITS_ARTIFACTS_CLAIMS_PROJECT=* -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # The nameserver's own deployment. TWO PUBLISHES, BOTH PROTOCOLS: the deployed container
            # is what answers a registrar's delegation, so a -p missing here is a domain that stops
            # resolving at the first cutover, and a missing /tcp loses every answer too big for a UDP
            # packet. The port is the same knob the seed publishes (QITS_DNS_PORT), because a
            # delegation cannot follow a port that moved.
            #
            # NO DATASOURCE ENV AND NO VOLUME: `resources: postgresql:db` in its deployments.yml is
            # what gets it a store, and the deployer injects the triple from its registry row before
            # the successor starts — pinning it here would outlive a rotation and break the
            # deployment it looks like it is configuring. The seed compose block spells the same three
            # variables because it starts this container before any deployer exists.
            #
            # No machine auth: the record API's write guard is qits.dns.token, which this platform
            # leaves blank, and there is no gateway route to reach it from outside qits-net.
            qits.platform.deployments.run-args.qits-platform-dns=-p ${DNS_PORT}:8053/udp -p ${DNS_PORT}:8053/tcp -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080${DNS_IDENTITY_ARGS}
            qits.platform.deployments.run-args.qits-stt=-v qits-stt-data:/data -e QITS_SPEECH_HOME=/data/speech -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # THE VOLUME STAYS AND THE DATASOURCE ENV IS GONE, which is the whole shape of this service's
            # move to postgres. /data is not the database's — it is QITS_PROJECTS_DATA_DIR below, the git
            # mirrors this service clones and the credentials beside them, files that no database
            # replaced. Both stores are declared instead: `resources: postgresql:db, postgresql:epics:
            # qits_epics` in projects' deployments.yml, and the deployer injects QITS_RESOURCE_DB_* and
            # QITS_RESOURCE_EPICS_* from its registry. Pinning either triple here would outlive a
            # rotation and break the deployment it looks like it is configuring.
            #
            # projects no longer mounts the shared repositories volume at all — it clones its own git mirrors
            # over the wire, through qits.artifacts.url, into its own data dir. QITS_PROJECTS_DATA_DIR is
            # spelled here rather than left to the image default (${user.home}/...), which resolves to the
            # literal "?" under this image's passwd-less UID 1001.
            #
            # QITS_REPOSITORIES_GIT_PUSH_TOKEN is the SAME token qits-githost's hook checks, three lines
            # above. projects advances refs on the git host by pushing now, and the default branch is
            # protected here, so without the token every pull that fast-forwards main is refused. A branch
            # delete deliberately sends no token.
            #
            # NO QITS_PROJECTS_AGENT_IMAGE, and its absence is the fix. It used to name
            # qits/project-agent:native — a tag built by hand on one machine, which the unwrap deleted
            # and no pipeline rebuilt, so every refinement agent start failed on an image that did not
            # exist. qits-projects-daemon's release pipeline publishes qits/project-agent:<version>
            # now, and qits-projects ships the registry-qualified pin, which a release train moves. An
            # override here would freeze that pin at whatever this file last said. Same reason
            # qits-workspaces' run-args do not name QITS_WORKSPACE_IMAGE.
            #
            # The docker socket, on the same terms qits-ci and qits-workspaces have it: DockerAgentRuntime
            # shells `docker run` to create a project's agent container, so without the socket every agent
            # start fails at the runtime rather than at a config check. The mount hands this container
            # control of the host daemon, which is root-equivalent — the service's own docs call supplying
            # it a deliberate deployment act rather than an image default, and this line IS that act.
            #
            # QITS_PROJECTS_OWN_HOST and QITS_PROJECTS_AGENT_GIT_BASE are the two addresses an agent
            # container is handed at creation: this service's own wire name, and the git host it clones
            # from. The image ships pre-rename defaults (qits-projects, qits-artifacts), which resolve to
            # nothing on this platform, so a container created from them never dials back and its boot
            # clone fails. Both are spelled here, the first with the environment's own prefix.
            #
            # QITS_GITHOST_URL REPLACED QITS_ARTIFACTS_URL, and the rename is the point rather than a
            # tidy-up: this service mirrors and pushes git, and git is qits-githost now. The old key is
            # gone from the image, so a deployment still passing it configures NOTHING and the service
            # falls back to a default — which is exactly the silence the rename was made to break.
            # Scheme, host and port only; the /git/<repoId> path is the caller's.
            qits.platform.deployments.run-args.qits-projects=-v qits-projects-data:/data -v /var/run/docker.sock:/var/run/docker.sock --group-add ${DOCKER_GID} -e QITS_PROJECTS_DATA_DIR=/data/mirrors -e QITS_GITHOST_URL=http://${ENV_NAME}-qits-githost:8080 -e QITS_REPOSITORIES_GIT_PUSH_TOKEN=${PUSH_TOKEN} -e QITS_PROJECTS_OWN_HOST=${ENV_NAME}-qits-projects -e QITS_PROJECTS_AGENT_GIT_BASE=http://${ENV_NAME}-qits-githost:8080/git -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # The volume stays for the same reason qits-projects' does: /data is this service's own tree of
            # per-repository files, not a database. Both its stores — its own and the eventstream outbox —
            # are declared in its deployments.yml and injected by the deployer, so no datasource env is
            # here either.
            # QITS_GITHOST_URL is where release PUSHES the release commit — the git host, over HTTP, so
            # the ordinary SCMPublishCommit is published and the ordinary pipeline builds it. It replaced
            # qits.artifacts.url, which named one service back when one service was both; the old key is
            # gone from the image, so passing it configures nothing at all. QITS_EVENTS_URL is where the
            # outbox drains to.
            # QITS_WORKSPACE_GIT_HOST (qits.workspace.git-host) is the address a WORKSPACE container uses to
            # reach this platform — git clone/push, OTLP, the agent's MCP servers and the daemon control
            # socket are all composed as http://<this>:8080/... It must be spelled, because the sentinel
            # "auto" is wrong on this topology and wrong silently: auto detects WSL2 and answers the primary
            # LAN IPv4, which is the address of the machine when qits runs ON the host — but qits-workspaces
            # runs in a container here, so what it measures is its OWN container's address and every
            # container->platform URL 404s. The gateway, not qits-workspaces or the artifacts service: it is
            # the one name on qits-net that fronts a WHOLE environment. Not the edge either — a workspace
            # belongs to a tier, and the gateway is the tier's own front door, while the edge exists to pick
            # between tiers for traffic that arrived from outside.
            qits.platform.deployments.run-args.qits-workspaces=-v qits-workspaces-data:/data -v /var/run/docker.sock:/var/run/docker.sock --group-add ${DOCKER_GID} -e QITS_PROJECTS_URL=http://${ENV_NAME}-qits-projects:8080 -e QITS_GITHOST_URL=http://${ENV_NAME}-qits-githost:8080 -e QITS_EVENTS_URL=http://${ENV_NAME}-qits-events:8080 -e QITS_WORKSPACE_GIT_HOST=${ENV_NAME}-qits-gateway -e QITS_WORKSPACES_RELEASE_ENTRY_BRANCH=environment/${ENV_NAME} -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # The reading surface over qits-artifacts' docs repository. ONE line and no volume, because
            # this service stores nothing — `latest` is a query over the store's rows rather than a
            # pointer it holds, so a redeploy loses nothing and there is no datasource URL to spell.
            #
            # An ENVIRONMENT service since the byte-plane split, and it had to become one: it reads
            # bundles out of a store that is now per-tier, so a single platform-wide reader would be one
            # front door onto whichever tier's shelf it was pointed at. The address is this tier's own,
            # and it is the SAME value qits-ci injects into a publishing step as $QITS_DOCS_URL, so the
            # publisher and the reader cannot disagree about where documentation lives.
            qits.platform.deployments.run-args.qits-docs=-e QITS_DOCS_ARTIFACTS_URL=http://${ENV_NAME}-qits-artifacts:8080/artifacts/docs/docs -e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # THE BUS. One line and no volume: this service's log is a database it declares
            # (`resources: postgresql:db`) and is handed by the deployer, and its image dropped the /data
            # mount point with the H2 — it writes nothing that outlives the container.
            #
            # The seed compose block spells the triple this line must not, and the asymmetry is the usual
            # one: compose starts the bus before any deployer exists, while a pin here would be appended
            # after the deployer's own injection — docker keeps the last -e — and would outlive the
            # rotation that first deployment performs.
            qits.platform.deployments.run-args.qits-events=-e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            # The receiver's own telemetry, addressed to itself. That is the consistent answer rather than
            # the clever one: qits-observability is an ordinary OTLP client like every application above,
            # and leaving it on the dead default would keep exactly one container spamming retries. This
            # application needed nothing beyond its image until the address had to be spelled, which is why
            # it had no line at all.
            qits.platform.deployments.run-args.qits-observability=-e QITS_OBSERVABILITY_URL=http://${ENV_NAME}-qits-observability:8080
            """;
}
